using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Reflection;using System.Windows.Forms;using Prometheus;
class ProbeTimeline:Timeline{public Keys Modifiers;protected override Keys CurrentModifiers{get{return Modifiers;}}public void Down(int x,int y){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,x,y,0));}public void RightClick(int x,int y){OnMouseDown(new MouseEventArgs(MouseButtons.Right,1,x,y,0));}public new void Move(int x,int y){OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,x,y,0));}public void Up(int x,int y){OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,x,y,0));}}
class FixUiTests0254{static int n;static void Check(bool b,string s){if(!b)throw new Exception("FAIL "+s);n++;Console.WriteLine("PASS "+s);}static IEnumerable<Control> Children(Control c){foreach(Control x in c.Controls){yield return x;foreach(Control y in Children(x))yield return y;}}[STAThread]static void Main(string[] a){Application.EnableVisualStyles();Tools.Root=System.IO.Path.GetFullPath(a[0]);var p=Store.Load(System.IO.Path.Combine(Tools.Root,"demo","Demostracion.prometheus.json"));var track=p.Active.tracks.First(x=>x.kind=="video");using(var t=new ProbeTimeline{Project=p,Width=1000,Height=360,ActiveTool=Timeline.ToolMode.Razor}){int cuts=0,ranges=0;double ra=0,rb=0;t.RazorCut=x=>cuts++;t.RangeTrimAction=(id,x,y)=>{ranges++;ra=x;rb=y;};int rowY=t.TrackTop(track.id)+12;int click=(int)t.X(1.1);t.Down(click,rowY);t.Up(click,rowY);Check(cuts==1,"Razor click on a clip splits without requiring drag");t.Down(click,rowY);int finish=(int)t.X(1.6);t.Move(finish,rowY);t.Up(finish,rowY);Check(ranges==1&&ra<rb&&Math.Abs((rb-ra)-0.5)<0.06,"Razor cut and continued drag reports the true timeline range");}using(var trim=new ProbeTimeline{Project=Store.Copy(p),Width=1000,Height=360}){var c=trim.Project.Active.clips.First(x=>x.track_id==track.id);int rowY=trim.TrackTop(track.id)+12;int left=(int)trim.ClipBounds(c).Left;bool? edge=null;trim.TrimClip=(id,isLeft,time)=>edge=isLeft;trim.Down(left+1,rowY);trim.Move(left+18,rowY);trim.Up(left+18,rowY);Check(edge==true,"normal cursor trims from left edge");edge=null;c=trim.Project.Active.clips.First(x=>x.track_id==track.id);int right=(int)trim.ClipBounds(c).Right;trim.Down(right-1,rowY);trim.Move(right-18,rowY);trim.Up(right-18,rowY);Check(edge==false,"normal cursor trims from right edge");double rolled=-1;trim.RollClip=(l,r,at)=>rolled=at;var bounds=trim.Project.Active.clips.Where(x=>x.track_id==track.id).OrderBy(x=>x.timeline_start.Seconds).ToList();bounds[1].timeline_start=Rational.Time(bounds[0].End);int seam=(int)trim.X(bounds[0].End);trim.Down(seam,rowY);trim.Move(seam+22,rowY);trim.Up(seam+22,rowY);Check(rolled>bounds[0].End&&Math.Abs(rolled-bounds[0].End-0.4)<0.06,"Roll Edit drag follows the cut boundary");double slipped=-1;trim.ActiveTool=Timeline.ToolMode.Slip;trim.SlipClip=(id,source)=>slipped=source;c=trim.Project.Active.clips.First(x=>x.track_id==track.id);int center=(int)(trim.ClipBounds(c).Left+trim.ClipBounds(c).Width/2);trim.Down(center,rowY);trim.Move(center+22,rowY);trim.Move(center+44,rowY);trim.Up(center+44,rowY);Check(Math.Abs(slipped-0.8)<0.06,"content movement uses total drag distance instead of accumulating mouse events");}

var uiForward=Store.Copy(p);var vf=uiForward.Active.clips.First(c=>uiForward.Active.tracks.Find(t=>t.id==c.track_id).kind=="video");var vfTrack=vf.track_id;var vf2=Store.Json().Deserialize<Clip>(Store.Json().Serialize(Store.Fields(vf)));vf2.id=Store.Id();vf2.name="later";vf.timeline_start=Rational.Frame(0);vf.duration=Rational.Frame(1);vf2.timeline_start=Rational.Frame(4);vf2.duration=Rational.Frame(1);uiForward.Active.clips.Clear();uiForward.Active.link_groups.Clear();uiForward.Active.clips.Add(vf);uiForward.Active.clips.Add(vf2);var uiForwardEditor=new Editor();uiForwardEditor.Reset(uiForward);using(var t=new ProbeTimeline{Project=uiForwardEditor.Project,Width=1200,Height=300,Zoom=50,Snap=false}){string id=uiForwardEditor.Project.Active.clips.First().id;t.Selection=new List<string>{id};t.InsertClip=(clip,at,destTrack)=>{uiForwardEditor.InsertSelection(t.Selection,clip,at,destTrack);};var c=uiForwardEditor.Project.Active.clips.Find(x=>x.id==id);int y=t.TrackTop(c.track_id)+20;int xpos=(int)(t.X(c.timeline_start.Seconds)+c.duration.Seconds*t.Zoom/2);t.Modifiers=Keys.Control;t.Down(xpos,y);t.Move(xpos+400,y);t.Up(xpos+400,y);Check(uiForwardEditor.Project.Active.clips.Find(z=>z.id==id).timeline_start.Seconds==7,"Ctrl-drag gesture dispatches forward Insert/Reorder through the timeline");}
var uiBack=Store.Copy(uiForward);var backId=uiBack.Active.clips.First().id;var uiBackEditor=new Editor();uiBackEditor.Reset(uiBack);uiBackEditor.Commit(q=>q.Active.clips.Find(c=>c.id==backId).timeline_start=Rational.Frame(7));using(var t=new ProbeTimeline{Project=uiBackEditor.Project,Width=1200,Height=300,Zoom=50,Snap=false}){t.Selection=new List<string>{backId};t.InsertClip=(clip,at,destTrack)=>uiBackEditor.InsertSelection(t.Selection,clip,at,destTrack);var c=uiBackEditor.Project.Active.clips.Find(z=>z.id==backId);int y=t.TrackTop(c.track_id)+20;int xpos=(int)(t.X(c.timeline_start.Seconds)+c.duration.Seconds*t.Zoom/2);t.Modifiers=Keys.Control;t.Down(xpos,y);t.Move(xpos-350,y);t.Up(xpos-350,y);Check(uiBackEditor.Project.Active.clips.Find(z=>z.id==backId).timeline_start.Seconds==0,"Ctrl-drag gesture dispatches backward Insert/Reorder through the timeline");}
using(var t=new ProbeTimeline{Project=Store.Copy(p),Width=1000,Height=360}){var c=t.Project.Active.clips.First(x=>t.Project.Active.tracks.Find(z=>z.id==x.track_id).kind=="video");t.Selection=new List<string>{c.id};int xpos=(int)(t.ClipBounds(c).Left+t.ClipBounds(c).Width/2),y=(int)t.ClipBounds(c).Top+10;t.Modifiers=Keys.Control;t.Down(xpos,y);t.Up(xpos,y);Check(!t.Selection.Contains(c.id),"Ctrl-click toggles selection without starting a reorder");}
 typeof(Prometheus.App).GetField("Capture",BindingFlags.Public|BindingFlags.Static).SetValue(null,true);using(var form=new MainForm()){var help=(ToolTip)typeof(MainForm).GetField("help",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(form);var buttons=Children(form).OfType<Button>().Where(b=>!String.IsNullOrEmpty(b.AccessibleName)).ToList();Check(buttons.Count>=7,"mouse toolbar controls expose accessible names");Check(buttons.Any(b=>String.IsNullOrEmpty(b.Text)&&b.AccessibleName=="Seleccionar"),"selection tool uses the native arrow cursor without a text label");Check(buttons.All(b=>!b.Text.Any(Char.IsWhiteSpace)),"mouse tool options show icons without text");Check(buttons.All(b=>help.GetToolTip(b)==b.AccessibleName),"each mouse tool has a visible matching tooltip");}var gapProject=Store.Copy(p);var gapTrack=gapProject.Active.tracks.Where(x=>x.kind=="video").Select(x=>new{Track=x,Clips=gapProject.Active.clips.Where(c=>c.track_id==x.id).OrderBy(c=>c.timeline_start.Seconds).ToList()}).OrderByDescending(x=>x.Clips.Count).First();if(gapTrack.Clips.Count<2)throw new Exception("gap fixture needs two video clips");gapTrack.Clips[1].timeline_start=Rational.Frame(gapTrack.Clips[0].End+2);double gapMid=gapTrack.Clips[0].End+1;using(var gap=new ProbeTimeline{Project=gapProject,Width=1000,Height=360}){int gy=gap.TrackTop(gapTrack.Track.id)+12;int gx=(int)gap.X(gapMid);gap.Down(gx,gy);Check(gap.SelectedGapTrack==gapTrack.Track.id&&gap.SelectedGapStart<gap.SelectedGapEnd,"click selects and highlights an intermediate gap");int contexts=0;gap.GapContext=(id,at,point)=>contexts++;gap.RightClick(gx,gy);Check(contexts==1&&gap.SelectedGapTrack==gapTrack.Track.id,"right click opens context for the selected gap");}

typeof(Prometheus.App).GetField("Capture",BindingFlags.Public|BindingFlags.Static).SetValue(null,true);using(var form=new MainForm()){var editor=(Editor)typeof(MainForm).GetField("editor",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(form);var timeline=(Timeline)typeof(MainForm).GetField("timeline",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(form);editor.Reset(gapProject);timeline.Project=editor.Project;timeline.SelectedGapTrack=gapTrack.Track.id;timeline.SelectedGapStart=gapTrack.Clips[0].End;timeline.SelectedGapEnd=gapTrack.Clips[1].timeline_start.Seconds;typeof(MainForm).GetMethod("Delete",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(form,null);var remaining=editor.Project.Active.clips.Where(c=>c.track_id==gapTrack.Track.id).OrderBy(c=>c.timeline_start.Seconds).ToList();Check(Math.Abs(remaining[0].End-remaining[1].timeline_start.Seconds)<0.000001,"Delete closes a selected gap");}Console.WriteLine("PASS "+n+" UI regression checks");}}







